import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> [side, price, qty_remaining, seq]
    seq_counter = 0

    def clean_buy():
        while buy_heap and (buy_heap[0][2] not in book or book[buy_heap[0][2]][2] <= 0):
            heapq.heappop(buy_heap)

    def clean_sell():
        while sell_heap and (sell_heap[0][2] not in book or book[sell_heap[0][2]][2] <= 0):
            heapq.heappop(sell_heap)

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                book[oid][2] = 0
                del book[oid]
            continue

        oid = order[1]
        side = order[2]
        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            clean_sell()
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                if top_id not in book or book[top_id][2] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and price is not None and top_price > price:
                    break
                resting = book[top_id]
                trade_qty = min(remaining, resting[2])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                resting[2] -= trade_qty
                if resting[2] <= 0:
                    del book[top_id]
                    heapq.heappop(sell_heap)
                clean_sell()
        else:
            clean_buy()
            while remaining > 0 and buy_heap:
                neg_price, top_seq, top_id = buy_heap[0]
                top_price = -neg_price
                if top_id not in book or book[top_id][2] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and price is not None and top_price < price:
                    break
                resting = book[top_id]
                trade_qty = min(remaining, resting[2])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                resting[2] -= trade_qty
                if resting[2] <= 0:
                    del book[top_id]
                    heapq.heappop(buy_heap)
                clean_buy()

        if typ == 'limit' and remaining > 0:
            book[oid] = [side, price, remaining, seq_counter]
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, seq_counter, oid))
            seq_counter += 1
        elif typ != 'limit':
            pass

    return trades

